    #[test]
    fn output_artifact_round_trip_is_exact_and_truncation_is_refused() {
        let root = tempfile::tempdir().unwrap();
        let path = root.path().join("output.bin");
        let output = CapturedOutput {
            frames: vec![image(&[1, 2, 3])],
            fps: 24,
            audio: Some(AudioRecord {
                samples: vec![0.5],
                sample_rate: 48_000,
                channels: 1,
            }),
        };
        write_captured_output(&path, &output).unwrap();
        assert_eq!(
            read_captured_output(&path).unwrap().frames[0].pixels,
            vec![1, 2, 3]
        );
        let mut bytes = fs::read(&path).unwrap();
        bytes.pop();
        fs::write(&path, bytes).unwrap();
        assert!(read_captured_output(&path)
            .unwrap_err()
            .to_string()
            .contains("truncated"));
    }

    #[test]
    fn observed_geometry_comes_from_output_and_rejects_malformed_frames() {
        let output = CapturedOutput {
            frames: vec![
                ImageRecord {
                    width: 2,
                    height: 1,
                    pixels: vec![1; 6],
                },
                ImageRecord {
                    width: 2,
                    height: 1,
                    pixels: vec![2; 6],
                },
            ],
            fps: 24,
            audio: None,
        };
        assert_eq!(observed_geometry(&output).unwrap(), (2, 1, 2, 24));

        let mut changed = output.clone();
        changed.frames[1].width = 1;
        assert!(observed_geometry(&changed)
            .unwrap_err()
            .to_string()
            .contains("inconsistent or malformed"));

        let mut truncated = output;
        truncated.frames[0].pixels.pop();
        assert!(observed_geometry(&truncated)
            .unwrap_err()
            .to_string()
            .contains("inconsistent or malformed"));
    }

    #[test]
    fn quant_candidate_accepts_a_distinct_explicit_bf16_snapshot_identity_only() {
        let receipt = bf16_receipt();
        let candidate = measurement_case("ltx25-int8-convrot-blackwell-v1").unwrap();
        let hardware = HardwareIdentity {
            gpu_name: receipt.gpu_name.clone(),
            driver_version: receipt.driver_version.clone(),
            compute_cap: (12, 0),
            generation: Ltx25GpuGeneration::ConsumerBlackwellSm120,
            physical_ordinal: 0,
        };
        assert!(reference_receipt_matches_campaign(
            &receipt,
            candidate,
            &hardware,
            &receipt.inference_revision,
            &receipt.executable_sha256,
            &receipt.model_revision,
            &receipt.bundle_subdir,
        ));
        assert!(reference_receipt_matches_bundle(
            &receipt,
            &receipt.model_revision,
            &receipt.model_inventory_sha256,
            &receipt.runtime_bundle_sha256,
            &receipt.selected_bundle_sha256,
        ));
        let candidate_inventory = "9".repeat(64);
        assert_ne!(candidate_inventory, receipt.model_inventory_sha256);

        assert!(!reference_receipt_matches_campaign(
            &receipt,
            candidate,
            &hardware,
            &receipt.inference_revision,
            &"0".repeat(64),
            &receipt.model_revision,
            &receipt.bundle_subdir,
        ));
        assert!(!reference_receipt_matches_campaign(
            &receipt,
            candidate,
            &hardware,
            &receipt.inference_revision,
            &receipt.executable_sha256,
            &"0".repeat(40),
            &receipt.bundle_subdir,
        ));
        let mut wrong_reference = receipt.clone();
        wrong_reference.reference_model_inventory_sha256 = "0".repeat(64);
        assert!(!reference_receipt_matches_bundle(
            &wrong_reference,
            &receipt.model_revision,
            &receipt.model_inventory_sha256,
            &receipt.runtime_bundle_sha256,
            &receipt.selected_bundle_sha256,
        ));
    }

